import{_ as n,a0 as o,w as l,s as f,I as a,x as t,a1 as r,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"使用 Fstransform 轉換文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fstransform 轉換文件系統 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fstransform 轉換文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fstransform 轉換文件系統 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180813 Convert file systems with Fstransform","title":"使用 Fstransform 轉換文件系統","tag":"201808","desc":""},"relativePath":"201808/20180813 Convert file systems with Fstransform.md","filePath":"[post].md"}'),p={name:"201808/20180813 Convert file systems with Fstransform.md"};function m(u,s,g,h,b,x){const e=o("Link");return l(),f("div",null,[s[18]||(s[18]=a("h1",{id:"使用-fstransform-轉換文件系統",tabindex:"-1"},[t("使用 Fstransform 轉換文件系統 "),a("a",{class:"header-anchor",href:"#使用-fstransform-轉換文件系統","aria-label":"Permalink to “使用 Fstransform 轉換文件系統”"},"​")],-1)),s[19]||(s[19]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/08/converting-filesystems-816x345.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=t("很少有人知道他們可以將文件系統從一種類型轉換為另一種類型而不會丟失數據（即非破壞性的）。這可能聽起來像魔術，但 ",-1)),r(e,{href:"https://github.com/cosmos72/fstransform"},{default:i(()=>[...s[0]||(s[0]=[t("Fstransform",-1)])]),_:1}),s[2]||(s[2]=t(" 可以幾乎以任意組合將 ext2、ext3、ext4、jfs、reiserfs 或 xfs 分區轉換成另一類型。更重要的是，它可以直接執行，而無需格式化或複製數據。除此之外，還有一點好處：Fstransform 也可以處理 ntfs、btrfs、fat 和 exfat 分區。",-1))]),s[20]||(s[20]=d('<h3 id="在運行之前" tabindex="-1">在運行之前 <a class="header-anchor" href="#在運行之前" aria-label="Permalink to “在運行之前”">​</a></h3><p>Fstransform 存在一些警告和限制，因此強烈建議在嘗試轉換之前進行備份。此外，使用 Fstransform 時需要注意一些限制：</p><ul><li>你的 Linux 內核必須支持源文件系統和目標文件系統。聽起來很明顯，如果你想使用 ext2、ext3、ext4、reiserfs、jfs 和 xfs 分區，這樣不會出現風險。Fedora 支持所有分區，所以沒問題。</li><li>將 ext2 升級到 ext3 或 ext4 不需要 Fstransform。請使用 Tune2fs。</li><li>源文件系統的設備必須至少有 5％ 的可用空間。</li><li>你需要在開始之前卸載源文件系統。</li><li>源文件系統存儲的數據越多，轉換的時間就越長。實際速度取決於你的設備，但預計它大約為每分鐘 1GB。大量的硬鏈接也會降低轉換速度。</li><li>雖然 Fstransform 被證明是穩定的，但請備份源文件系統上的數據。</li></ul><h3 id="安裝説明" tabindex="-1">安裝説明 <a class="header-anchor" href="#安裝説明" aria-label="Permalink to “安裝説明”">​</a></h3><p>Fstransform 已經是 Fedora 的一部分。使用以下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fstransform</span></span></code></pre></div><h3 id="轉換" tabindex="-1">轉換 <a class="header-anchor" href="#轉換" aria-label="Permalink to “轉換”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/08/Screenshot_20180805_230116.png" alt=""></p><p><code>fstransform</code> 命令的語法非常簡單：<code>fstransform &lt;源設備&gt; &lt;目標文件系統&gt;</code>。請記住，它需要 root 權限才能運行，所以不要忘記在開頭添加 <code>sudo</code>。這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fstransform /dev/sdb1 ext4</span></span></code></pre></div><p>請注意，無法轉換根文件系統，這是一種安全措施。請改用測試分區或實驗性 USB 盤。與此同時，Fstransform 會在控制台中有許多輔助輸出。最有用的部分是預計完成時間，讓你隨時瞭解該過程需要多長時間。同樣，在幾乎空的驅動器上的幾個小文件將使 Fstransform 在一分鐘左右完成其工作，而更多真實世界的任務可能需要數小時的等待時間。</p><h3 id="更多支持的文件系統" tabindex="-1">更多支持的文件系統 <a class="header-anchor" href="#更多支持的文件系統" aria-label="Permalink to “更多支持的文件系統”">​</a></h3><p>如上所述，可以嘗試在 ntfs、btrfs、fat 和 exfat 分區使用 Fstransform。這些類型是早期實驗性的，沒有人能保證完美轉換。儘管如此，還是有許多成功案例，你可以通過在測試分區上使用示例數據集測試 Fstransform 來添加自己的成功案例。可以使用 <code>--force-untested-file-systems</code> 參數啓用這些額外的文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fstransform /dev/sdb1 ntfs --force-untested-file-systems</span></span></code></pre></div><p>有時，該過程可能會因錯誤而中斷。請放心再次執行命令 —— 它可能最終會在兩、三次嘗試後完成轉換。</p><hr>',16)),a("p",null,[s[4]||(s[4]=t("via: ",-1)),r(e,{href:"https://fedoramagazine.org/transform-file-systems-in-linux/"},{default:i(()=>[...s[3]||(s[3]=[t("https://fedoramagazine.org/transform-file-systems-in-linux/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=t("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/atolstoy/"},{default:i(()=>[...s[5]||(s[5]=[t("atolstoy",-1)])]),_:1}),s[10]||(s[10]=t(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[t("geekpi",-1)])]),_:1}),s[12]||(s[12]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[t("Linux中國",-1)])]),_:1}),s[17]||(s[17]=t(" 榮譽推出",-1))])])}const T=n(p,[["render",m]]);export{F as __pageData,T as default};
